from pathlib import Path
from html import escape as e
import json,collections
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'data/apps.json').read_text());NATIVE=json.loads((ROOT/'data/native-checks.json').read_text())
STATUS={'STARTUP_WINDOW_STABLE':('启动观察稳定','Stable startup window'),'INCONCLUSIVE':('需复核','Inconclusive'),'OBSERVED_UNSTABLE':('观察到不稳定','Instability observed'),'NOT_SUPPORTED':('该样本不支持','Sample unsupported'),'NO_RECORD':('未取得记录','No record')}
SECTIONS={'观测边界与安全状态':'Observation scope and security state','身份与 Framework':'Identity and framework','Binder 与系统服务':'Binder and system services','文件、FD 与路径':'Files, file descriptors and paths','进程与 Procfs':'Processes and procfs','ART、Linker 与 Maps':'ART, linker and memory maps','CPU、ABI 与页大小':'CPU, ABI and page size','对象跨接口一致性':'Object consistency across interfaces'}
def tx(lang,a,b):return a if lang=='zh'else b
def report_link(lang):return 'compatibility'+('.en'if lang=='en'else'')+'.html'
def teaser(lang):
 t=lambda a,b:tx(lang,a,b);link=report_link(lang)
 out=f'<section class="app-showcase"><div class="app-showcase-top"><div><p class="eyebrow">APP COMPATIBILITY</p><h2>{t("178 款应用，14 个类别。","178 apps. 14 categories.")}</h2></div><p>{t("微信、抖音、京东、WPS，还有阅读、工具、医疗和出行应用。逐项查看版本和历史结果。","WeChat, Douyin, JD, WPS, plus reading, utilities, health and travel apps. Check the versions and historical results for each.")}</p></div><div class="app-list real-icons">'
 for a in DATA['apps'][:32]:out+=f'<a class="app-tile" href="{link}#app-{e(a["package"])}"><img class="app-icon" src="{a["icon"]}" width="64" height="64" loading="lazy" alt=""><strong>{e(a["name"])}</strong></a>'
 return out+f'</div><div class="catalog-teaser-foot"><p class="matrix-note">{t("真实图标取自归档 APK。178 款为固定样本，其中 172 款有历史记录；不表示当前版本全部功能通过。","Real icons from archived APKs. The fixed corpus contains 178 apps, with historical records for 172; this is not a full-feature pass list for the current release.")}</p><a class="button primary" href="{link}#app-catalog">{t("浏览全部 178 款","Browse all 178 apps")} ↗</a></div></section>'
def compatibility(lang):
 t=lambda a,b:tx(lang,a,b);link=report_link(lang);evidence='evidence'+('.en'if lang=='en'else'')+'.html'
 s=f'<section class="section compat-section four-dimensions" id="compatibility"><div class="section-heading"><p class="eyebrow">COMPATIBILITY / FOUR DIMENSIONS</p><h2>{t("系统、应用、加固，","Android, apps, hardening,")}<br>{t("还有原生一致性。","and native consistency.")}</h2><p>{t("能装在哪个 Android 版本，哪些应用跑过，遇到加固时表现如何，原生接口是否一致。四个维度分别验证。","Which Android versions have been tested? Which apps run? How do protection mechanisms behave? Are native interfaces consistent? We track these separately.")}</p></div><nav class="compat-dimension-nav" aria-label="{t("兼容性维度","Compatibility dimensions")}">'
 for num,anchor,zh,en in [('01','android-support','Android 版本','Android versions'),('02','app-coverage','应用覆盖面','App coverage'),('03','hardening','加固场景','App hardening'),('04','native-consistency','原生一致性','Native consistency')]:s+=f'<a href="#{anchor}"><span>{num}</span>{t(zh,en)} <b>↘</b></a>'
 s+=f'</nav><article class="compat-panel" id="android-support"><div class="compat-panel-title"><span>01 / ANDROID</span><h3>{t("版本和设备，分别列清楚。","Versions and devices, listed separately.")}</h3></div><div class="table-wrap"><table><thead><tr><th>Android</th><th>{t("验证环境","Environment")}</th><th>{t("已核对的范围","Reviewed scope")}</th></tr></thead><tbody>'
 for ver,zz,ee,zz2,ee2 in [('13 / API 33','小米 10 · 真机','Xiaomi 10 · Physical device','JNI 初始化、状态隔离、基础网络与定位','JNI initialization, state isolation, basic network and location'),('15 / API 35','小米 12 Pro · 真机','Xiaomi 12 Pro · Physical device','核心组件、Agent、内存与流量检查','Core components, agent, memory and traffic inspection'),('16 / API 36','小米 17 Pro、平板 · 真机','Xiaomi 17 Pro and tablet · Physical devices','基础组件；平板另有横屏与小窗实拍','Core components; separate tablet landscape and floating-window capture'),('17 / API 37','ARM64 模拟器 · 4 KB / 16 KB','ARM64 emulator · 4 KB / 16 KB','应用启动、Guest native 加载与 Agent UI','App startup, guest native loading and Agent UI')]:s+=f'<tr><td><strong>{ver}</strong></td><td>{t(zz,ee)}</td><td>{t(zz2,ee2)}</td></tr>'
 s+=f'</tbody></table></div><p class="matrix-note">{t("以上为不同制品的限定场景记录，模拟器与真机分列。Android 14 未纳入本次已核对档案；16 KB 验证不等于所有旧版 SO 都兼容。","These are scoped records from different builds. Emulator and device results are separate. Android 14 is not in this reviewed archive; 16 KB tests do not establish compatibility with every legacy SO.")} <a href="{evidence}">{t("详细范围","Details")} ↗</a></p></article>'
 s+=f'<article class="compat-panel" id="app-coverage"><div class="compat-panel-title"><span>02 / APP COVERAGE</span><h3>{t("大多数样本已有启动稳定记录。","Most samples have a stable startup record.")}</h3></div><div class="coverage-numbers"><div><strong>178</strong><span>{t("固定应用样本 · 14 类","Fixed app corpus · 14 categories")}</span></div><div><strong>161</strong><span>{t("至少一批有启动稳定记录","Stable startup in at least one batch")}</span></div><div><strong>143 / 171</strong><span>{t("小米 12：稳定 / 有记录","Xiaomi 12: stable / recorded")}</span></div><div><strong>156 / 164</strong><span>{t("平板：稳定 / 有记录","Tablet: stable / recorded")}</span></div></div><p>{t("来自手机 r44 与平板 r51 的历史克隆安装测试。335 条原始记录已逐一核对校验值。当前版本的专项修复、旧版本的失败和未取得记录的样本，分别保留。","Historical clone-install tests on phone build r44 and tablet build r51. All 335 source records were checksum-verified. Later targeted fixes, historical failures and missing records remain distinct.")}</p><a class="text-link" href="{link}#app-catalog">{t("按应用名、类别和结果筛选完整目录","Filter the full catalog by app, category and result")} ↗</a><p class="matrix-note">{t("“启动观察稳定”是原始检测标签，不代表登录、支付、长期运行或当前交付包的全功能通过。161 是跨批次并集，不是同一版本全量通过率。","“Stable startup window” is the source classification, not a sign-in, payment, endurance or current-release full-feature pass. 161 is a union across batches, not a single-build pass rate.")}</p></article>'
 s+=f'<article class="compat-panel" id="hardening"><div class="compat-panel-title"><span>03 / APP HARDENING</span><h3>{t("按保护机制验证，不只看壳的名字。","Test the mechanism, not just the packer name.")}</h3></div><div class="hardening-grid">'
 hard=[('Native code integrity','原生代码完整性','libc / linker 文件与内存代码视图；工行、每日记有特定版本启动修复记录。','File and memory code views for libc / linker. Specific ICBC and Daily Diary versions have startup-fix records.','限定场景有正例','Scoped positive results'),('ELF / JNI / dynamic loading','ELF、JNI 与动态加载','APK 内 SO、动态库依赖与动态代码路径；按实际 APK、ABI 和页大小核对。','Embedded SO files, native dependencies and dynamic-code paths, checked against the APK, ABI and page size.','按样本验证','Sample-specific validation'),('Direct system calls / procfs','直接系统调用与 procfs','覆盖常规 libc 调用之外的接口与进程视图；当前基础检测仍有 9 项差异。','Interfaces beyond conventional libc calls and process views; the current baseline still has 9 failed checks.','仍有已知差异','Known differences remain'),('ART / class loading','ART 与类加载','原调用、类加载与线程栈适配；微信有特定版本启动修复记录。','Original-call, class-loading and thread-stack adaptation; a specific WeChat version has a startup-fix record.','限定场景有正例','Scoped positive results'),('Multi-process / signals','多进程与信号处理','服务重建、子进程与信号语义分别验证；财联社受控崩溃重建通过不等于长期稳定。','Service recovery, child processes and signal semantics are checked separately. Controlled CLS crash recovery is not an endurance pass.','按具体合同验证','Contract-specific validation'),('RASP / anti-tampering','运行时自保护与防篡改','包括 Promon Shield 相关样本研究。汇丰香港、点点穿书仍有未解决场景。','Includes research on Promon Shield samples. HSBC Hong Kong and Diandian Chuanshu still have unresolved scenarios.','未全面通过','Not fully validated')]
 for term,title,zh,en,status,statuse in hard:s+=f'<div class="hardening-item"><span class="mini-label">{term}</span><h4>{t(title,term)}</h4><p>{t(zh,en)}</p><span class="scope-tag">{t(status,statuse)}</span></div>'
 s+=f'</div><p class="matrix-note">{t("不按厂商品牌宣称“全版本加固通吃”；特定应用的启动正例不能推广到同厂商全部产品。","No blanket claim covers every protection vendor or version. A startup result for one app does not apply to all products from the same vendor.")}</p></article>'
 s+=f'<article class="compat-panel" id="native-consistency"><div class="compat-panel-title"><span>04 / NATIVE CONSISTENCY</span><h3>{t("检测项和通过数，直接公开。","The checks and results are visible.")}</h3></div><div class="native-headline"><div><strong>58<span> / 77</span></strong><p>{t("系统一致性基础检测通过","System-consistency baseline checks passed")}</p></div><div><strong>31<span> / 48</span></strong><p>{t("其中 Native 相关检测通过","Native-related checks passed within that baseline")}</p></div></div><div class="result-bar" aria-hidden="true"><i style="flex:58" class="result-pass"></i><i style="flex:9" class="result-fail"></i><i style="flex:7" class="result-unknown"></i><i style="flex:2" class="result-ns"></i><i style="flex:1" class="result-info"></i></div><div class="result-legend"><span>58 PASS</span><span>9 FAIL</span><span>7 INCONCLUSIVE</span><span>2 NOT_SUPPORTED</span><span>1 INFO</span></div><p>{t("Native 相关检查涉及文件与 FD、进程与 procfs、ART / Linker / 内存映射、CPU / ABI / 页大小，以及对象跨接口一致性。下表按同一批原始结果分组。","Native-related checks cover files and FDs, processes and procfs, ART / linker / memory maps, CPU / ABI / page size, and object consistency across interfaces. The table groups one recorded run.")}</p><div class="table-wrap"><table><thead><tr><th>{t("原生检测方向","Native check area")}</th><th>PASS</th><th>{t("总项数","Total")}</th><th>{t("其余状态","Other results")}</th></tr></thead><tbody>'
 checks=[c for c in NATIVE['checks']if c['nativeRelated']]
 for sec in dict.fromkeys(c['section']for c in checks):
  rr=[c for c in checks if c['section']==sec];count=collections.Counter(c['status']for c in rr);others=' · '.join(f'{v} {k}'for k,v in count.items()if k!='PASS');s+=f'<tr><td>{t(sec,SECTIONS[sec])}</td><td>{count["PASS"]}</td><td>{len(rr)}</td><td>{others}</td></tr>'
 s+=f'</tbody></table></div><p class="matrix-note">{t("固定记录：2026-10-29，小米 12 Pro / API 35，de35bed9，Probe 1a078569。48 项是按 SYSCALL / NATIVE / LIBC / LINKER / XVIEW 检测 ID 归类的子集；不是 48 个互相独立的功能。专项历史数据另列，不与 77 项相加。","Fixed record: October 29, 2026, Xiaomi 12 Pro / API 35, de35bed9, Probe 1a078569. The 48-check subset uses SYSCALL / NATIVE / LIBC / LINKER / XVIEW IDs; it is not 48 independent features. Historical specialized suites are separate and are not added to the 77 checks.")}</p><a class="text-link" href="{link}#native-checklist">{t("查看全部 77 项及 9 项未通过结果","Inspect all 77 checks and the 9 failures")} ↗</a></article>'
 s+=f'<aside class="terminology"><p class="eyebrow">TERMINOLOGY</p><h3>{t("“影子模式”对应什么技术？","What does “Shadow Mode” refer to?")}</h3><p>{t("官网采用“Native 系统调用兼容层”描述原产品中的“影子模式”：通过系统调用拦截、路径与 procfs 视图投影、文件描述符语义适配，处理原生调用的兼容性。原生代码完整性与跨接口一致性是另外需要验证的性质。","This site calls the original product’s “Shadow Mode” the native system-call compatibility layer: system-call interposition, path and procfs view projection, and file-descriptor semantic adaptation. Native-code integrity and consistency across interfaces are properties that require separate validation.")}</p><div class="term-chips"><span>System-call interposition</span><span>Procfs view consistency</span><span>FD / OFD semantics</span><span>Native code integrity</span></div><p class="matrix-note">{t("Seccomp-BPF 是系统调用过滤机制，不等于完整虚拟机或完整安全沙箱；此处也不宣称拥有独立的内核 mount namespace。","Seccomp-BPF is a system-call filtering mechanism, not a full virtual machine or complete security sandbox. This does not claim an independent kernel mount namespace.")} <a href="https://docs.kernel.org/userspace-api/seccomp_filter.html">Linux Seccomp</a> · <a href="https://man7.org/linux/man-pages/man5/proc.5.html">proc(5)</a></p></aside><div class="compat-details"><article><span class="mini-label">TIKTOK</span><h3>{t("TikTok，不插卡也能看。","TikTok, without a SIM card.")}</h3><p>{t("已在无蜂窝模块的小米 Wi-Fi 平板上实测：无需 SIM 卡，访客模式加载、切换并播放推荐视频。使用时仍需可访问 TikTok 的网络；未验证国内网络直连。","Verified on a Wi-Fi-only Xiaomi tablet with no cellular radio: guest recommendations loaded, switched, and played without a SIM. A network that can reach TikTok is still required; direct mainland connectivity has not been verified.")}</p></article><article><span class="mini-label">READ THE RECORDS</span><h3>{t("历史矩阵与专项结果都保留。","Keep the matrix and targeted results.")}</h3><p><a href="{link}">{t("完整兼容性目录与检测清单","Full compatibility catalog and check list")} ↗</a></p><p><a href="{evidence}">{t("Agent、手机和平板实拍说明","Agent, phone and tablet capture notes")} ↗</a></p></article></div></section>'
 return s
def appendix(lang):
 t=lambda a,b:tx(lang,a,b);home='index'+('.en'if lang=='en'else'')+'.html'
 switch=''.join(f'<a href="compatibility{(".en"if k=="en"else"")}.html?lang={k}" data-language="{k}"'+(' aria-current="true"'if k==lang else'')+'>'+label+'</a>'for k,label in [('zh','中文'),('en','EN')])
 s=f'<!doctype html><html lang="{t("zh-CN","en")}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><script src="assets/locale.js?v=20261031-compat"></script><title>{t("Orbit · 应用兼容目录与原生检测","Orbit · App compatibility and native checks")}</title><meta name="description" content="{t("178款应用历史测试目录，真实图标、分设备结果和77项一致性检查。","178-app historical test catalog with real icons, device-specific results, and 77 consistency checks.")}"><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/style.css?v=20261031-compat"><link rel="stylesheet" href="assets/refresh.css?v=20261031-compat"><link rel="stylesheet" href="assets/compatibility.css?v=20261031-compat"><script defer src="assets/compatibility.js?v=20261031-compat"></script></head><body><header><a class="brand" href="{home}"><span class="logo"></span>orbit</a><nav><div class="language-switch" aria-label="Language">{switch}</div><a class="nav-contact" href="{home}#compatibility">{t("返回官网","Back to Orbit")} ↗</a></nav></header><main class="compat-report"><p class="eyebrow">THE COMPATIBILITY RECORD</p><h1>{t("应用兼容目录与检测记录。","App compatibility and test records.")}</h1><p class="report-lead">{t("178 款固定样本、14 个类别。172 款有历史记录，161 款至少在一个批次出现启动观察稳定；其中138款在两批均有稳定记录。335条记录的原文件校验值全部匹配。","178 fixed samples across 14 categories. 172 have historical records, 161 were startup-stable in at least one batch, and 138 in both. All 335 original record checksums matched.")}</p><p class="matrix-note">{t("小米12：r44 / Android15；平板：r51 / Android16，2026年10月历史克隆安装批次。不同制品分别计数，不合并为最新包通过率。图标来自原报告的归档APK资源，不表示品牌合作。","Xiaomi 12: r44 / Android 15; tablet: r51 / Android 16, historical clone-install batches from October 2026. Different builds are counted separately, not as a current-release pass rate. Icons are from archived APK resources in the original report and do not imply brand partnerships.")}</p><div class="report-jumps"><a href="#app-catalog">{t("应用目录","App catalog")} ↓</a><a href="#native-checklist">{t("77项检测","77 checks")} ↓</a><a href="data/apps.json">{t("下载应用数据","App data")} ↗</a></div><section id="app-catalog"><h2>{t("应用目录","App catalog")}</h2><div class="catalog-controls"><label>{t("搜索应用或包名","Search app or package")}<input type="search" id="app-search" placeholder="{t("例如：微信、WPS、com.tencent","For example: WeChat, WPS, com.tencent")}"></label><label>{t("类别","Category")}<select id="app-category"><option value="">{t("全部类别","All categories")}</option>'
 for zh,en in sorted({(a['category'],a['categoryEn'])for a in DATA['apps']}):s+=f'<option value="{e(zh)}">{t(zh,en)}</option>'
 s+=f'</select></label><label>{t("历史结果","Historical result")}<select id="app-status"><option value="">{t("全部结果","All results")}</option><option value="stable">{t("至少一批有稳定记录","Stable in at least one batch")}</option><option value="review">{t("需复核／不稳定／不支持","Inconclusive / unstable / unsupported")}</option><option value="missing">{t("两批均无记录","No record in either batch")}</option></select></label></div><p id="catalog-count" role="status" class="matrix-note">178 {t("款样本","samples")}</p><div class="compat-app-grid">'
 for a in DATA['apps']:
  states=[v['status']for v in a['outcomes'].values()];bucket='stable'if'STARTUP_WINDOW_STABLE'in states else'missing'if set(states)=={'NO_RECORD'}else'review'
  keywords=' '.join([a['name'],a['package'],a.get('alias',''),a['category'],a['categoryEn']])
  s+=f'<details id="app-{e(a["package"])}" class="compat-app" data-keywords="{e(keywords)}" data-category="{e(a["category"])}" data-bucket="{bucket}"><summary><img src="{a["icon"]}" width="56" height="56" loading="lazy" alt=""><span><strong>{e(a["name"])}</strong><small>{t(a["category"],a["categoryEn"])}</small></span><b>＋</b></summary><div class="app-record-detail"><code>{e(a["package"])}</code>'
  for key,zh,en in [('phone','小米12 · r44','Xiaomi 12 · r44'),('tablet','平板 · r51','Tablet · r51')]:
   r=a['outcomes'][key];state=STATUS[r['status']][0 if lang=='zh'else 1];s+=f'<p><span>{t(zh,en)}</span><strong class="record-{r["status"].lower()}">{state}</strong><small>v{e(r["version"])}</small></p>'
  if a.get('laterNote'):s+=f'<p class="later-note">{e(t(a["laterNote"],a["laterNoteEn"]))}</p>'
  s+=f'<small>{t("历史启动观察，不代表当前版本完整业务通过。","Historical startup observation, not a current-version full business-flow pass.")}</small></div></details>'
 s+=f'</div><button id="catalog-expand" class="button primary" hidden>{t("显示全部匹配应用","Show all matching apps")}</button><p class="matrix-note">{t("未取得记录不等于应用不兼容。具体App的新修复、设备差异与已知问题仍需另看专项结果。","A missing record does not mean an app is incompatible. Later fixes, device differences and known issues require their own targeted results.")}</p></section><section id="native-checklist"><p class="eyebrow">NATIVE / FRAMEWORK CONSISTENCY</p><h2>{t("固定77项，保留每种状态。","77 fixed checks. Every status retained.")}</h2><p>{t("2026-10-29 · 小米12 Pro / API35 · de35bed9 · Probe 1a078569。克隆安装、系统调用兼容层和原生代码一致性同时开启。58 PASS / 9 FAIL / 7 INCONCLUSIVE / 2 NOT_SUPPORTED / 1 INFO。","October 29, 2026 · Xiaomi 12 Pro / API 35 · de35bed9 · Probe 1a078569. Clone installation, syscall compatibility and native-code consistency were enabled together. 58 PASS / 9 FAIL / 7 INCONCLUSIVE / 2 NOT_SUPPORTED / 1 INFO.")}</p><p class="matrix-note">{t("Native子集按SYSCALL、NATIVE、LIBC、LINKER、XVIEW前缀统计：48项，31通过、9未通过、6不可判定、2不支持。它是官网的明确归类口径，不是新增测试或独立功能计数。英文页面保留原始检测ID，以便与原件对应。","The native subset uses SYSCALL, NATIVE, LIBC, LINKER and XVIEW prefixes: 48 checks, with 31 passes, 9 failures, 6 inconclusive and 2 unsupported. This is an explicit website grouping, not a new test or a count of independent features. Original check IDs are retained for traceability.")}</p><label class="native-filter-label">{t("筛选检查","Filter checks")} <select id="native-filter"><option value="all">{t("全部77项","All 77")}</option><option value="native">{t("原生相关48项","48 native-related")}</option><option value="FAIL">{t("9项未通过","9 failures")}</option><option value="PASS">{t("58项通过","58 passes")}</option></select></label><div class="table-wrap native-full-table"><table><thead><tr><th>{t("检测ID／名称","Check ID")}</th><th>{t("方向","Area")}</th><th>{t("结果","Result")}</th></tr></thead><tbody>'
 for c in NATIVE['checks']:
  s+=f'<tr data-check-status="{c["status"]}" data-native="{str(c["nativeRelated"]).lower()}"><td><code>{c["id"]}</code>'+ (f'<small>{e(c["title"])}</small>'if lang=='zh'else'')+f'</td><td>{t(c["section"],SECTIONS[c["section"]])}</td><td class="check-{c["status"].lower()}">{c["status"]}</td></tr>'
 s+=f'</tbody></table></div><p><a href="data/native-checks.json">{t("下载脱敏检测清单","Download the sanitized check list")} ↗</a></p><h3>{t("专项历史结果，单独计数。","Specialized historical results are separate.")}</h3><p>{t("代码读取与映射专项：libc与linker64的pread、private/shared mmap、raw shared mmap，在API35/36两机的物理与虚拟域分别8/8通过。文件与FD专项：API35两次虚拟冷进程6/6通过，含共享偏移、pread位置、FD复用、只读写入失败和并发读取；第6项为清理断言。它们来自2026-10-13/18的独立制品与套件，不与当前77项相加，也不代表任意竞争或阻塞情形均正确。","A code-read/mapping suite covered libc and linker64 pread, private/shared mmap and raw shared mmap, passing 8/8 in physical and virtual contexts on the API 35/36 test devices. A file/FD suite passed 6/6 in two API 35 virtual cold processes, covering shared offsets, pread position, FD reuse, rejected read-only writes and concurrent reads; its sixth assertion checks cleanup. These are separate October 13/18 builds and suites, not additions to the current 77 checks or proof for every race or blocking condition.")}</p><p class="matrix-note">{t("静态代码一致不等于并发原子性。当前已知缺口包括UID/procfs视图、宿主映射信息、map_files和smaps等，均保留为未通过或不可判定。","Static code consistency does not prove concurrent atomicity. Known gaps include UID/procfs views, host mapping information, map_files and smaps; failures and inconclusive results are retained.")}</p></section><section class="report-sources"><h2>{t("资料与术语","Sources and terminology")}</h2><p>{t("应用图标来自178包历史网页的APK声明图标及自适应图标资源：143项声明位图、22项自适应位图回退、9项前景位图、4项由原矢量资源导出。没有用字母或生成图替代应用标识。","The historical 178-app report supplies icons from APK declarations and adaptive resources: 143 declared bitmaps, 22 adaptive bitmap fallbacks, 9 foreground bitmaps and 4 exports from original vector resources. Letters or generated logos are not used as substitutes.")}</p><p>{t("记录索引：app-matrix-history；2026-10-29-proc-slot-candidate；2026-10-13-code-mapping-integration；2026-10-18-miniapk-shadow-suites。公开页仅包含汇总、检测ID和图标，不发布原始日志、设备标识或私有路径。","Record identifiers: app-matrix-history; 2026-10-29-proc-slot-candidate; 2026-10-13-code-mapping-integration; 2026-10-18-miniapk-shadow-suites. Public files contain summaries, check IDs and icons, excluding raw logs, device identifiers and private paths.")}</p><p><a href="https://docs.kernel.org/userspace-api/seccomp_filter.html">Linux: Seccomp BPF</a> · <a href="https://man7.org/linux/man-pages/man5/proc.5.html">Linux: proc(5)</a> · <a href="https://developer.android.com/guide/practices/page-sizes">Android: 16 KB page sizes</a></p><p><a href="{home}#compatibility">← {t("回到官网兼容性介绍","Back to the compatibility overview")}</a></p></section></main></body></html>'
 return s
